package com.pathland.view;

/**
 * A typed key for a scoped environment value (SwiftUI {@code EnvironmentValues}
 * key style). Identity-based: two keys are equal only if they are the same instance,
 * so a {@code static final EnvironmentKey<T>} per value is the idiom.
 *
 * <pre>{@code
 * public static final EnvironmentKey<Router> ROUTER = EnvironmentKey.of("router");
 * }</pre>
 */
public final class EnvironmentKey<T> {

    private final String name;

    private EnvironmentKey(String name) {
        this.name = name;
    }

    /** A named environment key (name is for debugging/reading — identity is by instance). */
    public static <T> EnvironmentKey<T> of(String name) {
        return new EnvironmentKey<>(name);
    }

    @Override
    public String toString() {
        return "EnvironmentKey[" + name + "]";
    }
}

package com.pathland.view;

import java.util.HashMap;
import java.util.Map;

/**
 * An immutable, hierarchical scope of environment values (SwiftUI
 * {@code EnvironmentValues}): a parent chain where each node adds (or overrides)
 * one {@link EnvironmentKey} → value binding. Lookup returns the nearest binding,
 * so a scoped {@code .environment(key, value)} overrides an outer one for its
 * subtree only. Values are resolved during render; structural slots re-apply the
 * incoming scope when they re-render their destination.
 *
 * <p>Built cheaply: {@link #with} returns a new node sharing the parent, so scoping
 * a large tree is O(1) per binding, not a full copy.
 */
public final class EnvironmentValues {

    private static final EnvironmentValues EMPTY = new EnvironmentValues(null, null, null);

    private final EnvironmentValues parent;
    private final EnvironmentKey<?> key;
    private final Object value;

    private EnvironmentValues(EnvironmentValues parent, EnvironmentKey<?> key, Object value) {
        this.parent = parent;
        this.key = key;
        this.value = value;
    }

    /** The empty scope (no bindings). */
    public static EnvironmentValues empty() {
        return EMPTY;
    }

    /** A scope extending {@code this} with {@code key → value} (nearest wins on read). */
    public <T> EnvironmentValues with(EnvironmentKey<T> key, T value) {
        return new EnvironmentValues(this, key, value);
    }

    /** The value bound to {@code key}, walking the chain; {@code null} when absent. */
    @SuppressWarnings("unchecked")
    public <T> T get(EnvironmentKey<T> key) {
        for (EnvironmentValues node = this; node != null; node = node.parent) {
            if (node.key == key) {
                return (T) node.value;
            }
        }
        return null;
    }

    /** A flattened view of the nearest bindings (for debugging/tests). */
    Map<EnvironmentKey<?>, Object> flattened() {
        Map<EnvironmentKey<?>, Object> out = new HashMap<>();
        for (EnvironmentValues node = this; node != null; node = node.parent) {
            if (node.key != null && !out.containsKey(node.key)) {
                out.put(node.key, node.value);
            }
        }
        return out;
    }

    @Override
    public boolean equals(Object o) {
        if (!(o instanceof EnvironmentValues other)) {
            return false;
        }
        return flattened().equals(other.flattened());
    }

    @Override
    public int hashCode() {
        return flattened().hashCode();
    }
}

package com.pathland.view;

/**
 * The rendering environment. Carries implicit, thread-local values that a parent
 * injects down the entire child tree (e.g. an active {@link ButtonStyle}), plus a
 * generic, hierarchical scope of {@link EnvironmentValues} keyed by
 * {@link EnvironmentKey} (SwiftUI {@code EnvironmentValues} style).
 *
 * <p>A {@code .environment(key, value)} modifier binds a value for the subtree it
 * wraps — nearest wins, so an inner binding overrides an outer one. The mount render
 * is synchronous and single-threaded, so a {@link ThreadLocal} is equivalent to
 * ScopedValue here while keeping the library on every LTS from Java 17.
 *
 * <p>Structural slots re-render their destination outside the container's render
 * path ({@code Emitter.reconcileSlot}); each node captures its incoming scope
 * ({@code PathlandNode.environmentForChildren}) so destinations that read a value
 * keep working on every re-render.
 */
public final class Environment {

    static final ThreadLocal<ButtonStyle> BUTTON_STYLE = new ThreadLocal<>();
    private static final ThreadLocal<EnvironmentValues> VALUES = ThreadLocal.withInitial(EnvironmentValues::empty);

    /** The default environment (no persistent state; buttons render with {@link PlainButtonStyle}). */
    public static final Environment DEFAULT = new Environment(null);

    private final com.pathland.view.state.PersistentState state;

    public Environment(com.pathland.view.state.PersistentState state) {
        this.state = state;
    }

    /** The button style active for the current render, defaulting to {@link PlainButtonStyle}. */
    public ButtonStyle buttonStyle() {
        ButtonStyle style = BUTTON_STYLE.get();
        return style != null ? style : PlainButtonStyle.INSTANCE;
    }

    /** The session's persistent state (null for a stateless environment). */
    public com.pathland.view.state.PersistentState state() {
        return state;
    }

    // --- generic environment values ---

    /** The current scope (empty at the top of a render). */
    public static EnvironmentValues current() {
        return VALUES.get();
    }

    /** Scoped {@code value} for {@code key}, read via the current thread-local scope. */
    public static <T> T value(EnvironmentKey<T> key) {
        return VALUES.get().get(key);
    }

    /** Scoped {@code value} for {@code key} on this environment instance. */
    public <T> T value(EnvironmentKey<T> key) {
        return current().get(key);
    }

    /** Temporarily set the active scope for a render (save/restore around it). */
    static void within(EnvironmentValues scope) {
        VALUES.set(scope);
    }

    /** Restore the previous active scope (must pair with a prior {@link #within}). */
    static void restore(EnvironmentValues previous) {
        VALUES.set(previous);
    }
}

package com.pathland.view;

/**
 * Scopes an {@link EnvironmentKey} → value binding down a subtree (SwiftUI
 * {@code .environment(...)}): the value is active only while the wrapped subtree
 * renders, and an outer binding is restored afterward. Applied via
 * {@code View#environment(EnvironmentKey, Object)}.
 */
public final class EnvironmentMod implements ViewModifier {

    private final EnvironmentKey<Object> key;
    private final Object value;

    @SuppressWarnings("unchecked")
    static <T> EnvironmentMod of(EnvironmentKey<T> key, T value) {
        return new EnvironmentMod((EnvironmentKey<Object>) key, value);
    }

    private EnvironmentMod(EnvironmentKey<Object> key, Object value) {
        this.key = key;
        this.value = value;
    }

    @Override
    public View body(View content) {
        return new EnvironmentView(content, key, value);
    }
}

package com.pathland.view;

import com.pathland.view.emit.PathlandNode;

/**
 * A view scoped to an environment value via the thread-local scope: the binding is
 * active only for this subtree's render, so values below inherit it without threading
 * a parameter through every {@link View#render} call (the {@code ButtonStyle} pattern,
 * generalized).
 */
final class EnvironmentView implements View {

    private final View content;
    private final EnvironmentKey<Object> key;
    private final Object value;

    EnvironmentView(View content, EnvironmentKey<Object> key, Object value) {
        this.content = content;
        this.key = key;
        this.value = value;
    }

    @Override
    public PathlandNode render(Environment env) {
        EnvironmentValues scope = Environment.current().with(key, value);
        EnvironmentValues previous = Environment.current();
        Environment.within(scope);
        try {
            return content.render(env);
        } finally {
            Environment.restore(previous);
        }
    }
}

