package com.pathland.server;

import com.pathland.view.ThemeData;
import com.pathland.view.View;

/**
 * The application's root-view factory — the single app-specific piece the server
 * runtime needs. A host (Spring Boot / Quarkus starter) provides one as a bean; the
 * runtime mounts a fresh root per session (views hold per-session {@code State}).
 *
 * <pre>{@code
 * @Bean PathlandApp pathlandApp() { return () -> new MyHomeView(); }
 * }</pre>
 */
@FunctionalInterface
public interface PathlandApp {

    /** A fresh root view for a new session. */
    View newRoot();

    /** The optional global theme (design-token overrides); {@code null} for none. */
    default ThemeData theme() {
        return null;
    }
}

package com.pathland.server;

/**
 * The transport seam (spec DSL.md §4.5): the server runtime sends delta frames through
 * this, so the session logic is framework-agnostic. Each starter adapts its WebSocket
 * type (Spring {@code WebSocketSession}, Quarkus {@code WebSocketConnection}) to it.
 */
public interface PathlandConnection {

    /** Send a self-contained delta/snapshot frame to this connection's client. */
    void send(byte[] bytes);

    /** Whether the connection can currently accept a send. */
    boolean isOpen();
}

package com.pathland.server;

import com.pathland.render.html.HtmlRenderer;
import com.pathland.view.Environment;
import com.pathland.view.Platform;
import com.pathland.view.emit.DateInput;
import com.pathland.view.emit.Emitter;
import com.pathland.view.emit.Frame;
import com.pathland.view.emit.FrameOpcodeSink;
import com.pathland.view.emit.RenderResult;
import com.pathland.view.signal.Signals;
import com.pathland.view.signal.WritableSignal;
import com.pathland.view.state.PersistentState;
import com.pathland.view.state.StateStore;
import com.pathland.view.transport.EnvironmentData;
import com.pathland.view.transport.Event;
import com.pathland.view.transport.FrameCodec;

import java.util.Map;
import java.util.function.Consumer;

/**
 * One Pathland application instance per session (1:1 with a client). Owns the session's
 * {@link PersistentState}, the retained tree, the fine-grained emitter, and the single
 * connection it sends deltas to — all transport-agnostic ({@link PathlandConnection}).
 *
 * <p>The platform environment (spec/OPCODE.md §Environment fields) seeds the app: the
 * initial route comes from its {@code ROUTE} field (a request URL on SSR; the DOM
 * client's first message over the WebSocket), delivered to the tree as the
 * {@code Platform.ACTIVE_PATH} signal. Later environment messages **enrich** the session
 * (viewport resizes, future fields) via {@link #applyEnvironment}.
 *
 * <p>State wiring is automatic: {@code State} fields in the app's views connect to the
 * store at mount. The connection is wired only <em>after</em> mount, so the mount frame
 * (already SSR'd) is never re-sent.
 */
public final class PathlandSession {

    private final PersistentState state;
    private final WritableSignal<String> activePath;

    private final FrameOpcodeSink sink;
    private final Emitter emitter;
    private final Map<Integer, Runnable> tapActions;
    private final Map<Integer, Runnable> navigateActions;
    private final Map<Integer, Consumer<String>> textInputs;
    private final Map<Integer, Consumer<Float>> valueInputs;
    private final Map<Integer, DateInput> dateInputs;
    private final Consumer<Event> navigateHandler;
    private final int rootId;

    private float viewportWidth = -1f;
    private float viewportHeight = -1f;

    private volatile PathlandConnection connection;

    public PathlandSession(String sessionId, StateStore store, PathlandApp app, EnvironmentData env) {
        this.state = new PersistentState(store, sessionId);
        // The active platform path is a host-provided signal (Platform.ACTIVE_PATH); the
        // app reads it, and a bound Router re-routes guard-aware on external changes.
        this.activePath = Signals.signal(env.route());

        this.sink = new FrameOpcodeSink() {
            @Override
            public void endFrame() {
                super.endFrame();
                Frame frame = frame();
                if (!frame.opcodes().isEmpty()) {
                    // The mount frame (emitted in the constructor, before the session
                    // attaches) is NOT sent — the client already has the whole UI from
                    // the HTML. Only deltas + resync snapshots go out.
                    send(frame);
                }
            }
        };
        this.emitter = new Emitter(sink, app.theme());

        // Mount wires State fields, then renders and emits the structural frame. The
        // active path is injected as a scoped environment value; any root works (with or
        // without navigation).
        RenderResult result = emitter.mount(
                app.newRoot().environment(Platform.ACTIVE_PATH, activePath),
                new Environment(state));
        this.tapActions = result.tapActions();
        this.navigateActions = result.navigateActions();
        this.textInputs = result.textInputs();
        this.valueInputs = result.valueInputs();
        this.dateInputs = result.dateInputs();
        this.navigateHandler = result.navigateHandler();
        this.rootId = result.rootId();
        applyEnvironment(env); // records viewport; the router already seeded from env.route()
    }

    /** Apply (or enrich) the platform environment after mount (viewport resizes, …). */
    public void applyEnvironment(EnvironmentData env) {
        activePath.set(env.route()); // re-route if the platform moved (guards run in the bound router)
        if (env.viewportWidth() > 0) {
            viewportWidth = env.viewportWidth();
        }
        if (env.viewportHeight() > 0) {
            viewportHeight = env.viewportHeight();
        }
    }

    /** Wire the live connection AFTER mount (the initial frame was already SSR'd). */
    public void connect(PathlandConnection connection) {
        this.connection = connection;
    }

    /** Re-send the current tree as a full snapshot (META::RESYNC). */
    public void resync() {
        emitter.renderFull();
    }

    private void send(Frame frame) {
        PathlandConnection conn = connection;
        if (conn == null || !conn.isOpen()) {
            connection = null;
            return;
        }
        byte[] bytes = FrameCodec.encodeFrame(frame);
        try {
            conn.send(bytes);
        } catch (Exception e) {
            connection = null;
        }
    }

    /** Route an inbound event batch (raw host → guest opcodes) into the app's bindings. */
    public void dispatch(byte[] message) {
        try {
            for (Event event : FrameCodec.decodeEvents(message)) {
                if (event.isPointerUp()) {
                    // A declared navigation intent (`.navigate/.push/.replace`) wins over a
                    // plain tap action — route it first (spec DSL.md §4.5).
                    Runnable nav = navigateActions.get(event.target());
                    if (nav != null) {
                        nav.run();
                    } else {
                        Runnable action = tapActions.get(event.target());
                        if (action != null) {
                            action.run();
                        }
                    }
                } else if (event.isTextChanged()) {
                    Consumer<String> sink = textInputs.get(event.target());
                    if (sink != null) {
                        sink.accept(event.text());
                    }
                } else if (event.isValueChanged()) {
                    Consumer<Float> sink = valueInputs.get(event.target());
                    if (sink != null) {
                        sink.accept(event.value());
                    }
                } else if (event.isDateChanged()) {
                    DateInput sink = dateInputs.get(event.target());
                    if (sink != null) {
                        sink.accept(event.days(), event.millisOfDay());
                    }
                } else if (event.isNavigate()) {
                    if (event.url() != null) {
                        // A URL (deep link / popstate): update the active path — a bound
                        // Router re-routes guard-aware, and any onPathChange listener fires.
                        activePath.set(event.url());
                    } else {
                        // "Back one step" has no path — only meaningful with a Router.
                        Consumer<Event> sink = navigateHandler;
                        if (sink != null) {
                            sink.accept(event);
                        }
                    }
                }
            }
        } catch (RuntimeException e) {
            log("dropping event batch: " + e.getMessage());
        }
    }

    /** Render the SSR HTML for this session's current tree (request thread). */
    public String renderHtml() {
        HtmlRenderer renderer = HtmlRenderer.tryInstance();
        if (renderer == null) {
            return "<!DOCTYPE html><html><body><h1>Pathland renderer unavailable</h1>"
                    + "<p>Build the Rust crate so libpathland_render_html is embedded in the "
                    + "pathland-render-html jar.</p></body></html>";
        }
        return renderer.render(sink.frame(), rootId)
                .replace("</body>", "<script src=\"/pathland-dom-renderer.js\" defer></script></body>");
    }

    /** Tear down: close the persistent state, unsubscribe the emitter, drop the connection. */
    public void close() {
        state.close();
        emitter.destroy();
        connection = null;
    }

    private static void log(String message) {
        System.out.println("[pathland] " + message);
    }
}

package com.pathland.server;

import com.pathland.view.state.StateStore;
import com.pathland.view.transport.EnvironmentData;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * The application registry: 1:1 sessions keyed by id. Each WebSocket connection owns one
 * {@link PathlandSession}; deltas flow only to that client (never broadcast). Transport-
 * agnostic — the framework starters adapt their connection type to {@link PathlandConnection}.
 *
 * <p>Sessions are created **lazily on the first inbound message**: the platform
 * environment ({@code META::ENVIRONMENT}, spec/OPCODE.md) arrives as the DOM client's
 * first message, and its {@code ROUTE} field seeds the router before mount — so a
 * deep-linked URL renders the right destination and the WebSocket tree stays consistent
 * with the SSR HTML. {@code open} only registers the pending connection; later
 * environment messages **enrich** the session via {@code applyEnvironment}.
 *
 * <p>All session work is serialized on a single actor thread (signals are single-threaded
 * by contract). Per-session SSR runs on the request thread against the thread-safe
 * {@link StateStore} (a throwaway {@link PathlandSession}).
 */
public final class PathlandRegistry {

    private static final int MAX_EVENT_BATCH = 1 << 16;

    private final PathlandApp app;
    private final StateStore store;

    private final ExecutorService actor = Executors.newSingleThreadExecutor(r -> {
        Thread t = new Thread(r, "pathland-actor");
        t.setDaemon(true);
        return t;
    });

    private final Map<String, PathlandSession> sessions = new ConcurrentHashMap<>();
    private final Map<String, PathlandConnection> pending = new ConcurrentHashMap<>();

    public PathlandRegistry(PathlandApp app, StateStore store) {
        this.app = app;
        this.store = store;
    }

    /** Render the SSR HTML for a session (request thread), seeding the router from the request path. */
    public String renderHtml(String sessionId, String route) {
        PathlandSession session = new PathlandSession(sessionId, store, app, EnvironmentData.of(route));
        try {
            return session.renderHtml();
        } finally {
            session.close();
        }
    }

    /** Register the connection for a session id; the session is created on its first message. */
    public void open(String sessionId, PathlandConnection connection) {
        actor.execute(() -> {
            PathlandSession previous = sessions.remove(sessionId);
            if (previous != null) {
                previous.close();
            }
            pending.put(sessionId, connection);
        });
    }

    /** Apply the platform environment: creates the session (seeded from its ROUTE field) on first contact, or enriches it after mount. */
    public void environment(String sessionId, EnvironmentData env) {
        actor.execute(() -> session(sessionId, env).applyEnvironment(env));
    }

    /** Route an inbound event batch to the owning session. */
    public void dispatch(String sessionId, byte[] message) {
        if (message.length > MAX_EVENT_BATCH) {
            return;
        }
        actor.execute(() -> session(sessionId, EnvironmentData.of("/")).dispatch(message));
    }

    /** Handle a META::RESYNC request: re-send the session's current tree as a snapshot. */
    public void resync(String sessionId) {
        actor.execute(() -> session(sessionId, EnvironmentData.of("/")).resync());
    }

    /** Close and remove a session (and drop any pending connection). */
    public void close(String sessionId) {
        actor.execute(() -> {
            pending.remove(sessionId);
            PathlandSession session = sessions.remove(sessionId);
            if (session != null) {
                session.close();
            }
        });
    }

    /** Shut down the registry: close every session and stop the actor. */
    public void shutdown() {
        for (PathlandSession session : sessions.values()) {
            session.close();
        }
        sessions.clear();
        pending.clear();
        actor.shutdown();
    }

    /** Create the session on first contact, wired to its pending connection. */
    private PathlandSession session(String sessionId, EnvironmentData env) {
        PathlandSession session = sessions.get(sessionId);
        if (session == null) {
            PathlandConnection connection = pending.remove(sessionId);
            session = new PathlandSession(sessionId, store, app, env);
            if (connection != null) {
                session.connect(connection);
            }
            sessions.put(sessionId, session);
        }
        return session;
    }
}

package com.pathland.server;

import com.pathland.state.redis.RedisStateStore;
import com.pathland.view.state.StateStore;

/**
 * Default {@link StateStore} selection: Redis when reachable, otherwise the supplied
 * fallback (typically an in-memory store). The app may override with its own
 * {@code StateStore} bean.
 */
public final class StateStores {

    private StateStores() {}

    /** A Redis store when reachable, else {@code fallback}. */
    public static StateStore redisOrFallback(StateStore fallback) {
        try {
            StateStore redis = new RedisStateStore.Provider().store();
            redis.load("probe", Object.class); // probe connectivity
            log("state store: redis");
            return redis;
        } catch (RuntimeException e) {
            log("state store: in-memory (Redis unavailable: " + e.getMessage() + ")");
            return fallback;
        }
    }

    private static void log(String message) {
        System.out.println("[pathland] " + message);
    }
}

package com.pathland.spring;

import com.pathland.server.PathlandConnection;
import org.springframework.web.socket.BinaryMessage;
import org.springframework.web.socket.WebSocketSession;

/** Adapts a Spring {@link WebSocketSession} to the transport-agnostic {@link PathlandConnection}. */
final class SpringConnection implements PathlandConnection {

    private final WebSocketSession session;

    SpringConnection(WebSocketSession session) {
        this.session = session;
    }

    @Override
    public void send(byte[] bytes) {
        try {
            session.sendMessage(new BinaryMessage(bytes));
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    @Override
    public boolean isOpen() {
        return session.isOpen();
    }
}

package com.pathland.spring;

import com.pathland.server.PathlandRegistry;
import com.pathland.view.transport.FrameCodec;
import org.springframework.web.socket.BinaryMessage;
import org.springframework.web.socket.CloseStatus;
import org.springframework.web.socket.WebSocketMessage;
import org.springframework.web.socket.WebSocketSession;
import org.springframework.web.socket.handler.AbstractWebSocketHandler;

import java.nio.ByteBuffer;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

/**
 * The live-updates WebSocket endpoint at {@code /ws}. Sessions are 1:1; the session id
 * rides the {@code session} cookie set on the SSR page. The id is resolved
 * <strong>once per connection</strong> and memoized, so every message (events, close)
 * routes to the same session even when the cookie is absent (e.g. a client with no SSR
 * visit). The actual session logic lives in the framework-agnostic {@link PathlandRegistry}.
 */
public class PathlandSocket extends AbstractWebSocketHandler {

    private final PathlandRegistry registry;
    private final Map<WebSocketSession, String> sessionIds = new ConcurrentHashMap<>();

    public PathlandSocket(PathlandRegistry registry) {
        this.registry = registry;
    }

    @Override
    public void afterConnectionEstablished(WebSocketSession session) {
        String id = resolveSessionId(session);
        sessionIds.put(session, id);
        registry.open(id, new SpringConnection(session));
    }

    @Override
    public void handleMessage(WebSocketSession session, WebSocketMessage<?> message) {
        if (message instanceof BinaryMessage binary) {
            byte[] bytes = toByteArray(binary.getPayload());
            if (FrameCodec.isResync(bytes)) {
                registry.resync(sessionId(session));
            } else if (FrameCodec.isEnvironment(bytes)) {
                // The DOM client's FIRST message: seeds the session (created lazily) from
                // the ROUTE field; later messages enrich the environment (viewport, …).
                registry.environment(sessionId(session), FrameCodec.decodeEnvironment(bytes));
            } else {
                registry.dispatch(sessionId(session), bytes);
            }
        }
    }

    @Override
    public void afterConnectionClosed(WebSocketSession session, CloseStatus status) {
        close(session);
    }

    @Override
    public void handleTransportError(WebSocketSession session, Throwable exception) {
        close(session);
    }

    private void close(WebSocketSession session) {
        String id = sessionIds.remove(session);
        if (id != null) {
            registry.close(id);
        }
    }

    /** The memoized session id for the connection (falling back to a fresh resolve). */
    private String sessionId(WebSocketSession session) {
        String id = sessionIds.get(session);
        if (id == null) {
            id = resolveSessionId(session);
            sessionIds.put(session, id);
        }
        return id;
    }

    /** The session id from the {@code session} cookie (case-insensitive), else a fresh id. */
    private String resolveSessionId(WebSocketSession session) {
        for (Map.Entry<String, List<String>> header : session.getHandshakeHeaders().entrySet()) {
            if (!"cookie".equalsIgnoreCase(header.getKey())) {
                continue;
            }
            for (String value : header.getValue()) {
                for (String part : value.split(";")) {
                    String[] kv = part.trim().split("=", 2);
                    if (kv.length == 2
                            && "session".equalsIgnoreCase(kv[0].trim())
                            && !kv[1].isBlank()) {
                        return kv[1].trim();
                    }
                }
            }
        }
        return UUID.randomUUID().toString();
    }

    /** Copy a {@link ByteBuffer} into a {@code byte[]} regardless of backing array. */
    private static byte[] toByteArray(ByteBuffer buffer) {
        ByteBuffer duplicate = buffer.duplicate();
        byte[] bytes = new byte[duplicate.remaining()];
        duplicate.get(bytes);
        return bytes;
    }
}

package com.pathland.spring;

import com.pathland.server.PathlandRegistry;
import org.springframework.core.io.ClassPathResource;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseCookie;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.CookieValue;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.ResponseBody;

import jakarta.servlet.http.HttpServletRequest;

import java.io.IOException;
import java.io.InputStream;
import java.util.UUID;

/**
 * Server-side rendering entry point. Sets a per-session cookie and renders that session's
 * persisted state. The browser sends the same cookie on the WebSocket handshake (1:1).
 *
 * <p>The initial route is part of the platform environment (spec/OPCODE.md §Environment
 * fields): the request path is synthesized into the environment's {@code ROUTE} field, so
 * a deep link like {@code /users/42} renders its destination on the first paint. The
 * WebSocket later enriches the environment (viewport, …).
 */
@Controller
public class PathlandIndexController {

    private final PathlandRegistry registry;

    public PathlandIndexController(PathlandRegistry registry) {
        this.registry = registry;
    }

    /**
     * The SPA catch-all: every path renders the session shell seeded at the request path.
     * Requests carrying an {@code Upgrade} header (the {@code /ws} WebSocket handshake) are
     * excluded so they reach the registered WebSocket handler, not this HTML renderer.
     */
    @GetMapping(value = "/{*path}", headers = "!Upgrade")
    @ResponseBody
    public ResponseEntity<String> index(
            @CookieValue(value = "session", required = false) String sessionId,
            HttpServletRequest request) {
        if (sessionId == null || sessionId.isBlank()) {
            sessionId = UUID.randomUUID().toString();
        }
        String route = request.getRequestURI(); // e.g. "/users/42" or "/"
        String html = registry.renderHtml(sessionId, route);
        ResponseCookie cookie = ResponseCookie.from("session", sessionId).path("/").build();
        return ResponseEntity.ok()
                .header(HttpHeaders.SET_COOKIE, cookie.toString())
                .contentType(MediaType.TEXT_HTML)
                .body(html);
    }

    /**
     * The single static asset — served explicitly so the {@code /{*path}} catch-all never
     * shadows it. Built by {@code lib/typescript} and copied into the app's
     * {@code src/main/resources/static}.
     */
    @GetMapping(value = "/pathland-dom-renderer.js", produces = "application/javascript")
    @ResponseBody
    public byte[] bundle() throws IOException {
        try (InputStream in = new ClassPathResource("static/pathland-dom-renderer.js").getInputStream()) {
            return in.readAllBytes();
        }
    }
}

package com.pathland.spring;

import com.pathland.server.PathlandApp;
import com.pathland.server.PathlandRegistry;
import com.pathland.server.StateStores;
import com.pathland.view.state.InMemoryStateStore;
import com.pathland.view.state.StateStore;
import org.springframework.boot.autoconfigure.AutoConfiguration;
import org.springframework.boot.autoconfigure.condition.ConditionalOnBean;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
import org.springframework.context.annotation.Bean;
import org.springframework.web.socket.config.annotation.WebSocketConfigurer;

/**
 * Spring Boot auto-configuration for Pathland (spec DSL.md §4.5). Activated when the app
 * provides a {@link PathlandApp} bean — so adding the starter without a root view is a
 * no-op, and providing one wires SSR + live deltas end to end:
 *
 * <pre>{@code
 * @Bean PathlandApp pathlandApp() { return () -> new MyHomeView(); }
 * }</pre>
 *
 * <p>Every bean is {@code @ConditionalOnMissingBean}, so the app can override the
 * {@link StateStore}, the socket, or the controller.
 */
@AutoConfiguration
@ConditionalOnBean(PathlandApp.class)
public class PathlandAutoConfiguration {

    /** Default state store: Redis when reachable, else in-memory. */
    @Bean
    @ConditionalOnMissingBean(StateStore.class)
    public StateStore pathlandStateStore() {
        return StateStores.redisOrFallback(new InMemoryStateStore());
    }

    /** The per-session registry (shut down with the application context). */
    @Bean(destroyMethod = "shutdown")
    @ConditionalOnMissingBean
    public PathlandRegistry pathlandRegistry(PathlandApp app, StateStore store) {
        return new PathlandRegistry(app, store);
    }

    /** The {@code /ws} WebSocket handler. */
    @Bean
    @ConditionalOnMissingBean
    public PathlandSocket pathlandSocket(PathlandRegistry registry) {
        return new PathlandSocket(registry);
    }

    /** Registers the socket at {@code /ws}. */
    @Bean
    public WebSocketConfigurer pathlandWebSocketConfigurer(PathlandSocket socket) {
        return registry -> registry.addHandler(socket, "/ws").setAllowedOrigins("*");
    }

    /** The SSR catch-all + static JS bundle. */
    @Bean
    @ConditionalOnMissingBean
    public PathlandIndexController pathlandIndexController(PathlandRegistry registry) {
        return new PathlandIndexController(registry);
    }
}

package com.pathland.quarkus;

import com.pathland.server.PathlandConnection;
import io.quarkus.websockets.next.WebSocketConnection;

/** Adapts a Quarkus {@link WebSocketConnection} to the transport-agnostic {@link PathlandConnection}. */
final class QuarkusConnection implements PathlandConnection {

    private final WebSocketConnection connection;

    QuarkusConnection(WebSocketConnection connection) {
        this.connection = connection;
    }

    @Override
    public void send(byte[] bytes) {
        connection.sendBinary(bytes).subscribe().with(ignored -> {}, failure -> {});
    }

    @Override
    public boolean isOpen() {
        return connection.isOpen();
    }
}

package com.pathland.quarkus;

import com.pathland.server.PathlandRegistry;
import com.pathland.view.transport.FrameCodec;
import io.quarkus.arc.Arc;
import io.quarkus.arc.ClientProxy;
import io.quarkus.websockets.next.OnBinaryMessage;
import io.quarkus.websockets.next.OnClose;
import io.quarkus.websockets.next.OnOpen;
import io.quarkus.websockets.next.WebSocket;
import io.quarkus.websockets.next.WebSocketConnection;
import jakarta.inject.Inject;

import java.util.UUID;

/**
 * The live-updates WebSocket endpoint at {@code /ws}. Sessions are 1:1: the session id is
 * carried by the {@code session} cookie set on the SSR page (the browser sends it on the
 * handshake), and each connection owns its own session. The id is resolved once per
 * connection and memoized. The session logic lives in the framework-agnostic
 * {@link PathlandRegistry}.
 */
@WebSocket(path = "/ws")
public class PathlandSocket {

    @Inject
    WebSocketConnection connection;

    @Inject
    PathlandRegistry registry;

    private volatile String sessionId;

    @OnOpen
    void open() {
        // Resolve the concrete connection while the session context is active: the CDI
        // bean is session-scoped, so its client proxy would fail off-thread. ClientProxy
        // unwraps it to the real connection, whose send methods work from any thread.
        WebSocketConnection resolved =
                ClientProxy.unwrap(Arc.container().instance(WebSocketConnection.class).get());
        registry.open(sessionId(), new QuarkusConnection(resolved));
    }

    @OnClose
    void close() {
        registry.close(sessionId());
    }

    @OnBinaryMessage
    void onBinary(byte[] message) {
        if (FrameCodec.isResync(message)) {
            registry.resync(sessionId());
        } else if (FrameCodec.isEnvironment(message)) {
            // The DOM client's FIRST message: seeds the session (created lazily) from the
            // ROUTE field; later messages enrich the environment (viewport, …).
            registry.environment(sessionId(), FrameCodec.decodeEnvironment(message));
        } else {
            registry.dispatch(sessionId(), message);
        }
    }

    /** The per-connection session id: the {@code session} cookie, or a fresh id memoized once. */
    private String sessionId() {
        String current = sessionId;
        if (current == null) {
            synchronized (this) {
                current = sessionId;
                if (current == null) {
                    current = resolveSessionId();
                    sessionId = current;
                }
            }
        }
        return current;
    }

    /** The session id from the {@code session} cookie (case-insensitive), else a fresh id. */
    private String resolveSessionId() {
        String cookie = connection.handshakeRequest().header("Cookie");
        if (cookie != null) {
            for (String part : cookie.split(";")) {
                String[] kv = part.trim().split("=", 2);
                if (kv.length == 2 && "session".equalsIgnoreCase(kv[0].trim()) && !kv[1].isBlank()) {
                    return kv[1].trim();
                }
            }
        }
        return UUID.randomUUID().toString();
    }
}

package com.pathland.quarkus;

import com.pathland.server.PathlandRegistry;
import jakarta.inject.Inject;
import jakarta.ws.rs.CookieParam;
import jakarta.ws.rs.GET;
import jakarta.ws.rs.Path;
import jakarta.ws.rs.PathParam;
import jakarta.ws.rs.Produces;
import jakarta.ws.rs.core.MediaType;
import jakarta.ws.rs.core.NewCookie;
import jakarta.ws.rs.core.Response;

import java.util.UUID;

/**
 * Server-side rendering entry point. Sets a per-session cookie and renders that session's
 * persisted state. The browser sends the same cookie on the WebSocket handshake (1:1).
 *
 * <p>The initial route is part of the platform environment (spec/OPCODE.md §Environment
 * fields): the request path is synthesized into the environment's {@code ROUTE} field, so
 * a deep link like {@code /users/42} renders its destination on the first paint.
 */
@Path("/")
public class IndexResource {

    @Inject
    PathlandRegistry registry;

    /** The root page (the route is {@code /}). */
    @GET
    @Produces(MediaType.TEXT_HTML)
    public Response index(@CookieParam("session") String sessionId) {
        return render("/", sessionId);
    }

    /**
     * Any other path (deep links) — a multi-segment catch-all. The negative lookahead
     * excludes the literal {@code ws} path so the {@code @WebSocket("/ws")} endpoint
     * handles the WebSocket upgrade. Quarkus serves the static JS bundle from
     * {@code META-INF/resources} before JAX-RS, so it is not shadowed.
     */
    @GET
    @Path("{path:(?!ws).*}")
    @Produces(MediaType.TEXT_HTML)
    public Response deep(@PathParam("path") String path, @CookieParam("session") String sessionId) {
        return render("/" + path, sessionId);
    }

    private Response render(String route, String sessionId) {
        if (sessionId == null || sessionId.isBlank()) {
            sessionId = UUID.randomUUID().toString();
        }
        String html = registry.renderHtml(sessionId, route);
        NewCookie cookie = new NewCookie.Builder("session").value(sessionId).path("/").build();
        return Response.ok(html).cookie(cookie).build();
    }
}

package com.pathland.quarkus;

import com.pathland.server.PathlandApp;
import com.pathland.server.PathlandRegistry;
import com.pathland.server.StateStores;
import com.pathland.view.state.InMemoryStateStore;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.inject.Disposes;
import jakarta.enterprise.inject.Produces;
import jakarta.inject.Inject;
import jakarta.inject.Singleton;

/**
 * CDI wiring for Pathland: builds the {@link PathlandRegistry} from the app's
 * {@link PathlandApp} bean and the default state store (Redis when reachable, else
 * in-memory), and shuts it down with the application. The app provides the root view:
 *
 * <pre>{@code
 * @ApplicationScoped
 * public class MyApp implements PathlandApp {
 *     public View newRoot() { return new MyHomeView(); }
 * }
 * }</pre>
 */
@ApplicationScoped
public class PathlandRegistryProducer {

    @Inject
    PathlandApp app;

    @Produces
    @Singleton
    PathlandRegistry registry() {
        return new PathlandRegistry(app, StateStores.redisOrFallback(new InMemoryStateStore()));
    }

    void shutdown(@Disposes PathlandRegistry registry) {
        registry.shutdown();
    }
}

