    @Test
    void environmentRefResolvesLazilyInsideBody() {
        // An EnvironmentRef field is a SwiftUI-@Environment-style lazy proxy: stored at
        // construction (when no scope is active) but resolved on access inside body(),
        // within the pushed scope of a `.environment(...)` ancestor.
        Router router = Navigation.navigator().route("/", Text.of("x")).build();
        com.pathland.view.EnvironmentRef<Router> ref = com.pathland.view.EnvironmentRef.of(Navigation.ROUTER);
        java.util.List<Router> seen = new java.util.ArrayList<>();

        View composite = new View() {
            @Override
            public View body() {
                seen.add(ref.get()); // read at render time, inside the active scope
                return Text.of("x");
            }
        };

        new Emitter(sink()).mount(composite.environment(Navigation.ROUTER, router), Environment.DEFAULT);
        assertEquals(1, seen.size());
        assertEquals(router, seen.get(0), "the env value is visible through the lazy ref");

        // Without the modifier the ref resolves to null (no scope binding).
        seen.clear();
        new Emitter(sink()).mount(composite, Environment.DEFAULT);
        assertEquals(1, seen.size());
        assertEquals(null, seen.get(0), "no binding → null, and construction-time read is avoided");
    }

