import {HStack} from '../stacks';
import {Text} from '../text';
import {Image} from '../image/image';
import {LabelStyleModification, LabelStyleOption, LineLimit} from '../../modifiers';
import {BaseView} from '../view';
import {A11yContext} from '../../accessibility/a11y-context-provider';

/**
 * The Label component displays a text title and an icon. It is a component for reuse in many elements like
 * buttons, menus, dropdowns etc.
 *
 * It supports multiple style modes via the labelStyle modifier:
 * - 'titleOnly'
 * - 'iconOnly'
 * - 'titleAndIcon'
 *
 * The title should always defined even if not rendered, as it will be used for accessibility concerns. If the label only
 * displays the icon, then it will still use the title as the accessibility value of the icon.
 *
 * Example usage:
 * ```
 * <ui-label title="Settings" icon="settings-icon.svg"></ui-label>
 * ```
 */
@Component({
  selector: 'ui-label',
  imports: [HStack, Text, Image, LineLimit],
  template: `
    <ui-hstack gap="2" alignment="center">
      @if (isIconPresented()) {
        <ui-image [src]="icon()!" [decorative]="true" height="1em" width="1em"></ui-image>
      }

      @if (isTitlePresented()) {
        <ui-text [text]="title()!" lineLimit="1"></ui-text>
      }
    </ui-hstack>`,
  host: {
    '[attr.aria-label]': 'title()'
  },
  encapsulation: ViewEncapsulation.ShadowDom,
})
export class Label extends BaseView {
  a11yContext = inject(A11yContext, { optional: true });
  labelStyle = inject(LabelStyleModification, { optional: true });
  /**
   * Text title displayed by the label.
   * If undefined or empty, no text will be rendered.
   */
  title = input<string | undefined>(undefined);

  /**
   * Optional icon source URL or path.
   * If undefined or empty, no icon will be rendered.
   */
  icon = input<string | undefined>(undefined);

  constructor() {
    super();
    effect(() => this.a11yContext?.label.set(this.title()));
  }

  style = computed<LabelStyleOption>(() => this.labelStyle?.option() ?? 'titleAndIcon');

  isIconPresented = computed(() =>
    this.icon() != null &&
    this.icon()?.trim() != '' &&
    (this.style() === 'iconOnly' || this.style() === 'titleAndIcon')
  );

  isTitlePresented = computed(() =>
    this.title() != null &&
    this.title()?.trim() != '' &&
    (this.style() === 'titleOnly' || this.style() === 'titleAndIcon')
  );
}

